const tr=k=>T[state.lang][k]||k;
function applyI18n(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=tr(e.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(e=>e.placeholder=tr(e.dataset.i18nPlaceholder));document.querySelectorAll('[data-i18n-title]').forEach(e=>e.title=tr(e.dataset.i18nTitle));renderThreads();renderApprovals();renderModelControls();renderMethods();if(state.capabilities)renderCapabilities(state.capabilities);if(state.selectedMethod){const info=readableMethodInfo(state.selectedMethod);$('methodHumanTitle').textContent=info.title;$('methodGroup').textContent=`${tr('methodGroup')} · ${info.group} · ${methodKindLabel($('methodKind').value)}`}$('statusLine')&&updateStatus()}
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const body=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(body.message||body.error||`HTTP ${r.status}`);e.status=r.status;e.body=body;throw e}return body}
async function rpc(method,params={},options={}){return(await api('/api/rpc',{method:'POST',body:JSON.stringify({method,params}),...options})).result}
const respond=(id,result)=>api('/api/respond',{method:'POST',body:JSON.stringify({id,result})});
const respondError=(id,error)=>api('/api/respond',{method:'POST',body:JSON.stringify({id,error})});
const hasRequest=m=>Boolean(state.methods?.requests?.some(x=>x.method===m));
function toast(text,kind=''){const e=document.createElement('div');e.className=`toast ${kind}`;e.textContent=text;$('toastRegion').append(e);setTimeout(()=>e.remove(),4500)}
function shortDate(v){if(!v)return'';const ms=v>1e10?v:v*1000;try{return new Intl.DateTimeFormat(state.lang==='zh'?'zh-CN':'en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(ms))}catch{return''}}
function threadTitle(t){return t?.name||t?.title||t?.preview||t?.id||'Thread'}
function threadStatus(t){return String(t?.status?.type||t?.status||'').toLowerCase()}
function isActiveOfficialStatus(value){return isOfficialActiveStatus(value)}
function normalizeThreads(r){return r?.data||r?.threads||r?.items||(Array.isArray(r)?r:[])}
async function refreshThreads(){const serial=state.threadListSerial=(state.threadListSerial||0)+1,view=Boolean(state.archivedView);try{const r=await rpc('thread/list',{limit:100,archived:view,sortKey:'updated_at',sortDirection:'desc'});if(serial!==state.threadListSerial||view!==Boolean(state.archivedView))return false;state.threads=normalizeThreads(r);state.threadsLoaded=true;renderThreads();return true}catch(e){if(serial===state.threadListSerial)console.warn(e);return false}}
function renderThreads(){const root=$('threadList');if(!root)return;const q=$('threadSearch')?.value.trim().toLowerCase()||'';const list=state.threads.filter(t=>!q||threadTitle(t).toLowerCase().includes(q)||String(t.id||'').toLowerCase().includes(q));const nodes=list.map(t=>{const d=document.createElement('div');d.className='thread'+(state.currentThread?.id===t.id?' active':'');d.setAttribute('role','listitem');const title=document.createElement('div');title.className='thread-title';title.textContent=threadTitle(t);const meta=document.createElement('div');meta.className='thread-meta';const dot=document.createElement('span');dot.className='thread-status-dot'+(isActiveOfficialStatus(t?.status)?' running':'');const txt=document.createElement('span');txt.textContent=[threadStatus(t),shortDate(t.updatedAt||t.createdAt)].filter(Boolean).join(' · ');meta.append(dot,txt);const row=document.createElement('div');row.className='thread-row-copy';row.append(title,meta);const actions=document.createElement('div');actions.className='thread-menu-wrap';const menuButton=document.createElement('button');menuButton.type='button';menuButton.className='thread-menu-button';menuButton.textContent='···';menuButton.title=tr('threadMenu');menuButton.setAttribute('aria-label',tr('threadMenu'));const menu=document.createElement('div');menu.className='thread-menu hidden';const addAction=(key,method,handler,danger=false)=>{const button=document.createElement('button');button.type='button';button.className=danger?'thread-menu-action danger':'thread-menu-action';button.textContent=tr(key);button.disabled=!canWebWrite(t?.id)||!hasRequest(method)||state.threadOperationBusy?.has(String(t?.id||''));button.onclick=async event=>{event.stopPropagation();menu.classList.add('hidden');if(button.disabled)return;await handler(t)};menu.append(button)};if(state.archivedView)addAction('unarchiveThread','thread/unarchive',unarchiveThread);else addAction('archiveThread','thread/archive',archiveThread);addAction('renameThread','thread/name/set',renameThread);addAction('deleteThread','thread/delete',deleteThread,true);menuButton.onclick=event=>{event.stopPropagation();document.querySelectorAll('.thread-menu:not(.hidden)').forEach(node=>{if(node!==menu)node.classList.add('hidden')});menu.classList.toggle('hidden')};actions.append(menuButton,menu);d.append(row,actions);d.onclick=()=>{closeMobileSidebar();selectThread(t.id)};return d});if(!nodes.length){const e=document.createElement('div');e.className='thread-meta';e.style.padding='12px';e.textContent=tr(state.archivedView?'noArchivedThreads':'noThreads');nodes.push(e)}root.replaceChildren(...nodes);const section=$('threadSectionLabel');if(section)section.textContent=tr(state.archivedView?'archivedSection':'recents');const archiveButton=$('archivedThreads');if(archiveButton){archiveButton.setAttribute('aria-pressed',String(Boolean(state.archivedView)));archiveButton.classList.toggle('active',Boolean(state.archivedView));const label=$('archivedThreadsLabel');if(label)label.textContent=tr(state.archivedView?'backToRecents':'archivedThreads')}}
function inferActiveTurnId(thread){return inferOfficialActiveTurnId(thread)}
function turnActiveForUi(turn){const id=String(turn?.id||'');return Boolean(id&&(id===String(state.activeTurnId||'')||id===String(state.officialActiveTurnId||'')))}
function textFromContent(content){if(!Array.isArray(content))return'';return content.map(x=>typeof x==='string'?x:(x?.text||x?.input_text||x?.output_text||x?.path||'')).filter(Boolean).join('\n')}
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function richText(text){const root=el('div','rich-text');const src=String(text||'');const fence=/```([^\n]*)\n([\s\S]*?)```/g;let last=0,m;const addPlain=s=>{s.split(/\n{2,}/).filter(Boolean).forEach(p=>{const n=el('p');n.textContent=p;root.append(n)})};while((m=fence.exec(src))){addPlain(src.slice(last,m.index));const wrap=el('details','code-block');const summary=el('summary','code-summary',m[1]?`${tr('codeBlock')} · ${m[1]}`:tr('codeBlock'));const pre=el('pre');const code=el('code','',m[2]);pre.append(code);const b=el('button','copy-code',tr('copy'));b.type='button';b.onclick=e=>{e.stopPropagation();navigator.clipboard?.writeText(m[2])};wrap.append(summary,pre,b);root.append(wrap);last=m.index+m[0].length}addPlain(src.slice(last));return root}
function itemKey(item){return item?.id||`${item?.type||'item'}-${Math.random().toString(36).slice(2)}`}
function statusKey(status){return officialStatusKey(status)}
