let authoritativeResync=null;
async function resyncAuthoritativeState(){
  if(authoritativeResync)return authoritativeResync;
  authoritativeResync=(async()=>{
    $('statusLine').textContent=tr('resyncing');
    const remembered=String(state.currentThread?.id||localStorage.getItem(LAST_THREAD_KEY)||'');
    await refreshMeta();
    await refreshThreads();
    const target=remembered||String(state.currentThread?.id||'');
    if(target)await selectThread(target,{quiet:true,force:true});
    else if(!state.currentThread?.id)await restoreLastThread();
  })();
  try{return await authoritativeResync}finally{authoritativeResync=null}
}
