function planSummary(snapshot){
  const plan=Array.isArray(snapshot?.plan)?snapshot.plan:[],total=plan.length;
  const active=plan.findIndex(step=>planStatus(step)==='inProgress'),pending=plan.findIndex(step=>planStatus(step)==='pending');
  const current=active>=0?active+1:pending>=0?pending+1:total;
  const completed=plan.filter(step=>planStatus(step)==='completed').length;
  return{total,current:Math.max(1,current),completed,complete:total>0&&completed===total};
}
function planHeadline(snapshot){
  const info=planSummary(snapshot);
  return info.complete?`${tr('planCompleted')} ${info.total}/${info.total}`:`${planProgressText(info.current,info.total)} · ${tr('planInProgress')}`;
}
