    row.append(icon,el('span','official-plan-step-label',label));row.dataset.status=status;row.setAttribute('aria-label',`${index+1}. ${label} · ${tr(status==='completed'?'planCompleted':status==='inProgress'?'planInProgress':'planPending')}`);list.append(row);
